let produtos = JSON.parse(localStorage.getItem("produtosEstoque")) || [];
let proximoId = produtos.reduce((maior, p) => Math.max(maior, p.id), 0) + 1;

const dinheiro = valor =>
    valor.toLocaleString("pt-BR", {
            style: "currency",
                    currency: "BRL"
                        });

                        function salvar() {
                            localStorage.setItem("produtosEstoque", JSON.stringify(produtos));
                            }

                            function mostrarTela(tela) {
                                document.getElementById("estoque").hidden = tela !== "estoque";
                                    document.getElementById("produtos").hidden = tela !== "produtos";

                                        atualizarSistema();
                                        }

                                        document.getElementById("formProduto").addEventListener("submit", function(event) {
                                            event.preventDefault();

                                                const nome = document.getElementById("nome").value.trim();
                                                    const categoria = document.getElementById("categoria").value.trim();
                                                        const quantidade = Number(document.getElementById("quantidade").value);
                                                            const preco = Number(document.getElementById("preco").value);

                                                                if (!nome || !categoria || quantidade < 0 || preco < 0 ||
                                                                        !Number.isFinite(quantidade) || !Number.isFinite(preco)) {
                                                                                alert("Preencha todos os campos corretamente.");
                                                                                        return;
                                                                                            }

                                                                                                produtos.push({
                                                                                                        id: proximoId++,
                                                                                                                nome,
                                                                                                                        categoria,
                                                                                                                                quantidade,
                                                                                                                                        preco
                                                                                                                                            });

                                                                                                                                                salvar();
                                                                                                                                                    this.reset();
                                                                                                                                                        atualizarSistema();

                                                                                                                                                            alert("Produto cadastrado com sucesso!");
                                                                                                                                                            });

                                                                                                                                                            function listarProdutos() {
                                                                                                                                                                const busca = document.getElementById("buscarProdutos").value.toLowerCase();

                                                                                                                                                                    const lista = produtos.filter(p =>
                                                                                                                                                                            p.nome.toLowerCase().includes(busca) ||
                                                                                                                                                                                    p.categoria.toLowerCase().includes(busca)
                                                                                                                                                                                        );

                                                                                                                                                                                            const tabela = document.getElementById("tabelaProdutos");
                                                                                                                                                                                                tabela.replaceChildren();

                                                                                                                                                                                                    lista.forEach(p => {
                                                                                                                                                                                                            const linha = document.createElement("tr");

                                                                                                                                                                                                                    const valores = [
                                                                                                                                                                                                                                p.id,
                                                                                                                                                                                                                                            p.nome,
                                                                                                                                                                                                                                                        p.categoria,
                                                                                                                                                                                                                                                                    p.quantidade,
                                                                                                                                                                                                                                                                                dinheiro(p.preco)
                                                                                                                                                                                                                                                                                        ];

                                                                                                                                                                                                                                                                                                valores.forEach(valor => {
                                                                                                                                                                                                                                                                                                            const celula = document.createElement("td");
                                                                                                                                                                                                                                                                                                                        celula.textContent = valor;
                                                                                                                                                                                                                                                                                                                                    linha.appendChild(celula);
                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                    const acoes = document.createElement("td");
                                                                                                                                                                                                                                                                                                                                                            const editar = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                    editar.textContent = "Editar";
                                                                                                                                                                                                                                                                                                                                                                            editar.className = "editar";
                                                                                                                                                                                                                                                                                                                                                                                    editar.onclick = () => editarProduto(p.id);

                                                                                                                                                                                                                                                                                                                                                                                            const excluir = document.createElement("button");
                                                                                                                                                                                                                                                                                                                                                                                                    excluir.textContent = "Excluir";
                                                                                                                                                                                                                                                                                                                                                                                                            excluir.className = "excluir";
                                                                                                                                                                                                                                                                                                                                                                                                                    excluir.onclick = () => excluirProduto(p.id);

                                                                                                                                                                                                                                                                                                                                                                                                                            acoes.append(editar, excluir);
                                                                                                                                                                                                                                                                                                                                                                                                                                    linha.appendChild(acoes);
                                                                                                                                                                                                                                                                                                                                                                                                                                            tabela.appendChild(linha);
                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                function listarEstoque() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                    const busca = document.getElementById("buscarEstoque").value.toLowerCase();

                                                                                                                                                                                                                                                                                                                                                                                                                                                        const lista = produtos.filter(p =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                p.nome.toLowerCase().includes(busca) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        p.categoria.toLowerCase().includes(busca)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const tabela = document.getElementById("tabelaEstoque");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    tabela.replaceChildren();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        lista.forEach(p => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const linha = document.createElement("tr");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const status = p.quantidade === 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ? ["Esgotado", "esgotado"]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                : p.quantidade <= 5
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ? ["Estoque baixo", "baixo"]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                : ["Disponível", "disponivel"];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const valores = [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    p.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                p.nome,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            p.quantidade,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        dinheiro(p.preco),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    dinheiro(p.quantidade * p.preco)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    valores.forEach(valor => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const celula = document.createElement("td");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            celula.textContent = valor;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        linha.appendChild(celula);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const celulaStatus = document.createElement("td");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const etiqueta = document.createElement("span");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        etiqueta.className = `status ${status[1]}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                etiqueta.textContent = status[0];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        celulaStatus.appendChild(etiqueta);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                linha.appendChild(celulaStatus);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        tabela.appendChild(linha);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function editarProduto(id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const produto = produtos.find(p => p.id === id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!produto) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const nome = prompt("Nome do produto:", produto.nome);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (nome === null) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const categoria = prompt("Categoria:", produto.categoria);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (categoria === null) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const quantidadeTexto = prompt("Quantidade:", produto.quantidade);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (quantidadeTexto === null) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const precoTexto = prompt("Preço unitário:", produto.preco);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (precoTexto === null) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const quantidade = Number(quantidadeTexto);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const preco = Number(precoTexto);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!nome.trim() || !categoria.trim() ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        quantidadeTexto.trim() === "" || precoTexto.trim() === "" ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                !Number.isFinite(quantidade) || quantidade < 0 ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        !Number.isFinite(preco) || preco < 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                alert("Dados inválidos. Tente novamente.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                produto.nome = nome.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    produto.categoria = categoria.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        produto.quantidade = quantidade;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            produto.preco = preco;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                salvar();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    atualizarSistema();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function excluirProduto(id) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const produto = produtos.find(p => p.id === id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!produto) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (confirm(`Deseja excluir o produto "${produto.nome}"?`)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        produtos = produtos.filter(p => p.id !== id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                salvar();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        atualizarSistema();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function atualizarSistema() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("totalProdutos").textContent = produtos.length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("totalUnidades").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            produtos.reduce((total, p) => total + p.quantidade, 0);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("valorEstoque").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        dinheiro(produtos.reduce((total, p) => total + p.quantidade * p.preco, 0));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            listarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                listarEstoque();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                atualizarSistema();